  ### Equations
  push!(__eqs, v_rel_0 ~ ModelingToolkit.D_nounits(frame_a.r_0) - [air.v_wind_x, air.v_wind_y, air.v_wind_z])
  push!(__eqs, v_rel_s ~ MultibodyComponents.resolve2(frame_a.R, v_rel_0))
  push!(__eqs, u ~ v_rel_s[1])
  push!(__eqs, V ~ sqrt(u ^ 2 + w ^ 2 + v_eps ^ 2))
  push!(__eqs, sa ~ w / V)
  push!(__eqs, ca ~ u / V)
  push!(__eqs, sa_abs ~ sqrt(sa ^ 2 + s_eps ^ 2))
  push!(__eqs, alpha ~ atan(w, u))
  push!(__eqs, sigma ~ 1 - (1 - 0.5 * (1 + tanh(M_stall * (sa_abs - sin(alpha_stall))))) * (1 - 0.5 * (1 - tanh(M_rev * ca))))
  push!(__eqs, CL_att ~ CL0 + CL_alpha * sa + CL_delta * d_eff)
  push!(__eqs, CL ~ (1 - sigma) * CL_att + sigma * (2 * sa * sa_abs * ca))
  push!(__eqs, CD ~ CD0 + (1 - sigma) * (CL_att ^ 2 / (3.141592653589793 * e_oswald * AR) + CD_delta * d_eff ^ 2) + sigma * (2 * sa ^ 2))
  push!(__eqs, CN ~ CL * ca + CD * sa)
  push!(__eqs, CM ~ CM0 + CM_delta * d_eff - sigma * 0.25 * CN)
  push!(__eqs, q ~ 0.5 * air.rho * (u ^ 2 + w ^ 2))
  push!(__eqs, L ~ q * S * CL)
  push!(__eqs, D ~ q * S * CD)
  push!(__eqs, F_s ~ [L * sa - D * ca, L * ca + D * sa, 0])
  push!(__eqs, frame_a.f ~ -F_s)
  push!(__eqs, frame_a.tau ~ -[0, 0, q * S * c * CM])

  ### Control Structures
  if has_induced_flow
    push!(__eqs, w ~ -v_rel_s[2] - w_induced)
  else
    push!(__eqs, w ~ -v_rel_s[2])
  end
  if has_control
    push!(__eqs, d_eff ~ delta)
  else
    push!(__eqs, d_eff ~ 0)
  end

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export AeroSurface
